@Entity
class Order {
  @Id Long id;

  @ManyToOne(fetch = FetchType.LAZY, optional = false)
  @JoinColumn(name = "CUSTOMER_ID", nullable = false)
  Customer customer;          // object reference stored as a key column
}

Customer customer(long customerId) throws SQLException {
    Customer cached = identityMap.get(customerId);
    if (cached != null) return cached;
    try (PreparedStatement ps = conn.prepareStatement(
            "SELECT id, name FROM customers WHERE id = ?")) {
        ps.setLong(1, customerId);
        ResultSet rs = ps.executeQuery();
        rs.next();
        Customer c = new Customer(rs.getLong("id"), rs.getString("name"));
        identityMap.put(customerId, c);       // one object per row
        return c;
    }
}
